	public static boolean enabled(EvaluationStrategy strategy) {
		QueryExecutionPolicy policy = strategy.getQueryExecutionPolicy();
		if (policy == null) {
			return false;
		}
		GraphJoinOptimization mode = policy.graphJoinOptimization();
		return mode == GraphJoinOptimization.AUTO || mode == GraphJoinOptimization.REQUIRE_RESTRICTED;
	}

	public static boolean enabled(EvaluationStrategy strategy, QueryEvaluationContext context) {
		return enabled(strategy) && AdaptiveFilterEvaluationStep.includesGraphRestrictionRegion(context);
	}

