	public static Map<String, String> projectionSources(Projection node) {
		Map<String, String> sources = new HashMap<>();
		Set<String> overwritten = new HashSet<>();
		for (ProjectionElem element : node.getProjectionElemList().getElements()) {
			String target = element.getProjectionAlias().orElse(element.getName());
			if (sources.putIfAbsent(target, element.getName()) != null) {
				overwritten.add(target);
			}
		}
		overwritten.forEach(sources::remove);
		return sources;
	}

	public static Function<String, String> extensionSources(Extension node) {
		Map<String, String> writes = new HashMap<>();
		for (ExtensionElem element : node.getElements()) {
			if (!TupleExprs.isEvaluatedExtensionElement(element)) {
				continue;
			}
			String source = element.getExpr() instanceof Var var && !var.hasValue()
					? writes.getOrDefault(var.getName(), var.getName())
					: null;
			writes.put(element.getName(), source);
		}
		return target -> writes.getOrDefault(target, target);
	}

