	private static PreparedRestrictionPlan binary(String rule, TupleExpr node, QueryEvaluationContext context,
			QueryEvaluationStep leftStep, QueryEvaluationStep rightStep, Supplier<CollectionFactory> collections,
			Function<Value, Value> capturer, BinaryProbe probe) {
		if (!(node instanceof BinaryTupleOperator original)) {
			throw new IllegalArgumentException("Restriction rule requires a binary operator");
		}
		PreparedRestrictionPlan left = childPlan(original.getLeftArg(), context, leftStep, collections, capturer);
		PreparedRestrictionPlan right = childPlan(original.getRightArg(), context, rightStep, collections, capturer);
		if (left == null || right == null || left.seekNames().isEmpty() && right.seekNames().isEmpty()) {
			return null;
		}
		RestrictionLayout layout = new RestrictionLayout(node.getBindingNames(), context);
		int[] leftSlots = transfer(layout, left.layout(), Function.identity());
		// A witness probe derives its keys from the retained original left row. Its direct transfer is empty even
		// for shared names, since an external key must still accept an originally unbound left slot.
		int[] rightSlots = transfer(layout, right.layout(),
				original instanceof LeftJoin || original instanceof Difference ? name -> null : Function.identity());
		Set<String> leftSeeks = mappedSeeks(layout, left, leftSlots);
		Set<String> rightSeeks = externalRightSeeks(original, right.seekNames());
		Set<String> seeks = new HashSet<>(leftSeeks);
		seeks.addAll(rightSeeks);
		var realization = left.blueprint().realization() == STABLE && right.blueprint().realization() == STABLE
				? STABLE
				: REPLAY;
		var blueprint = new RestrictionBlueprint(rule, realization, DISCARDABLE, slotMaps(leftSlots, rightSlots));
		return new PreparedRestrictionPlan(blueprint, layout, context, seeks, (input, owner) -> {
			RestrictedInvocation originalLeft = left.open(input, owner.child());
			RestrictedInvocation originalRight;
			try {
				originalRight = right.open(input, owner.child());
			} catch (RuntimeException | Error failure) {
				try {
					originalLeft.close();
				} catch (RuntimeException | Error closeFailure) {
					if (failure != closeFailure) {
						failure.addSuppressed(closeFailure);
					}
				}
				throw failure;
			}
			return new RestrictedInvocation() {
				@Override
				public CloseableIteration<BindingSet> probe(RestrictionFrame frame) {
					return residual(probe.apply(input, originalLeft, originalRight, frame,
							frame.transfer(left.layout(), leftSlots), frame.transfer(right.layout(), rightSlots)),
							frame);
				}

				@Override
				public void completeNormally() {
					originalLeft.completeNormally();
					originalRight.completeNormally();
				}

				@Override
				public boolean requiresReplay() {
					return originalLeft.requiresReplay() || originalRight.requiresReplay();
				}

				@Override
				public boolean hasSeekCapability() {
					return !leftSeeks.isEmpty() && originalLeft.hasSeekCapability()
							|| !rightSeeks.isEmpty() && originalRight.hasSeekCapability();
				}

				@Override
				public boolean requestCancellation() {
					return originalLeft.requestCancellation() | originalRight.requestCancellation();
				}

				@Override
				public void close() {
					try (RestrictedInvocation l = originalLeft; RestrictedInvocation r = originalRight) {
						// Close both even when one close fails.
					}
				}
			};
		});
	}

	private static PreparedRestrictionPlan childPlan(TupleExpr child, QueryEvaluationContext context,
			QueryEvaluationStep standard, Supplier<CollectionFactory> collections, Function<Value, Value> capturer) {
		if (!QueryEvaluationUtility.canDiscardWithoutEvaluation(child)) {
			return null;
		}
		PreparedRestrictionPlan plan = RestrictionPlanProvider.find(standard);
		return plan != null ? plan
				: replay("realization/opaque-output", child, context, standard, collections, capturer);
	}

	@FunctionalInterface
	private interface BinaryProbe {
		CloseableIteration<BindingSet> apply(BindingSet input, RestrictedInvocation left, RestrictedInvocation right,
				RestrictionFrame frame, RestrictionFrame leftFrame, RestrictionFrame rightFrame);
	}

	/** Conservative candidate keys. Each selected body still needs a plan from the actual prepared step. */
	public static boolean hasPotentialSeekFrom(TupleExpr operand, TupleExpr driver) {
		return hasPotentialSeekFrom(operand, driver, Set.of());
	}

	/** The optimizer may supply statement occurrences that a later magic-property rewrite consumes. */
	public static boolean hasPotentialSeekFrom(TupleExpr operand, TupleExpr driver, Set<StatementPattern> consumed) {
		return hasPotentialSeekFrom(potentialSeeks(operand, consumed), driver);
	}

	/** Allows a physical planner to retain its ordinary join when even the cheapest admissible probes lose. */
	public static boolean hasPotentialProfitableSeekFrom(TupleExpr operand, TupleExpr driver,
			EvaluationStatistics statistics) {
		Set<String> keys = potentialSeeks(operand, Set.of());
		if (!hasPotentialSeekFrom(keys, driver)) {
			return false;
		}
		if (operand instanceof Graph graph && RestrictionJoinCost.rejectsBroadValues(driver, graph, keys, statistics)) {
			if (graph.getParentNode() instanceof Join join && join.isRuntimeTelemetryEnabled()) {
				join.setStringMetricPlanned("graphRestrictionRefusal", "independent-cost");
			}
			return false;
		}
		return true;
	}

	private static boolean hasPotentialSeekFrom(Set<String> keys, TupleExpr driver) {
		if (driver instanceof BindingSetAssignment values) {
			// A declared VALUES column can be UNDEF everywhere. Unknown, potentially single-use sources
			// cannot be inspected or assumed to have no additional columns.
			return values.hasRepeatableBindingSets() ? !Collections.disjoint(keys, values.getPossibleBindingNames())
					: !keys.isEmpty();
		}
		return !Collections.disjoint(keys, driver.getBindingNames());
	}

	/** Candidate keys exported by the selector or the selected graph body. */
	public static Set<String> potentialGraphSeeks(Graph graph) {
		return potentialGraphSeeks(graph, Set.of());
	}

	private static Set<String> potentialGraphSeeks(Graph graph, Set<StatementPattern> consumed) {
		Set<String> names = new HashSet<>(potentialSeeks(graph.getArg(), consumed));
		if (!graph.getGraphName().isConstant() && !graph.getGraphName().hasValue()) {
			names.add(graph.getGraphName().getName());
		}
		return names;
	}

	private static Set<String> potentialSeeks(TupleExpr node, Set<StatementPattern> consumed) {
		OriginalPathDescriptor path = OriginalPathDescriptor.forRegion(node);
		if (path != null) {
			Set<String> exported = node.getBindingNames();
			Set<String> ends = new HashSet<>();
			for (var endpoint : List.of(path.start(), path.end())) {
				if (endpoint.fixed() == null && exported.contains(endpoint.name())) {
					ends.add(endpoint.name());
				}
			}
			return ends;
		}
		if (node instanceof StatementPattern pattern && pattern.getContextVar() == null
				&& !consumed.contains(pattern)
				&& !TupleFunctionMagicPropertyOptimizer.isMagicProperty(pattern, TupleFunctionRegistry.getInstance())) {
			Set<String> names = new HashSet<>();
			for (Var variable : List.of(pattern.getSubjectVar(), pattern.getPredicateVar(), pattern.getObjectVar())) {
				if (!variable.hasValue()) {
					names.add(variable.getName());
				}
			}
			return names;
		}
		if (node instanceof Graph graph) {
			return potentialGraphSeeks(graph, consumed);
		}
		if (node instanceof Projection projection) {
			return projectNames(projection.getBindingNames(), projectionSources(projection)::get,
					potentialSeeks(projection.getArg(), consumed));
		}
		if (node instanceof Extension extension
				&& extension.getElements().stream().allMatch(element -> movable(element.getExpr()))) {
			return projectNames(extension.getBindingNames(), extensionSources(extension),
					potentialSeeks(extension.getArg(), consumed));
		}
		if (node instanceof Filter filter && movable(filter.getCondition())) {
			return potentialSeeks(filter.getArg(), consumed);
		}
		if (node instanceof Distinct distinct) {
			return potentialSeeks(distinct.getArg(), consumed);
		}
		if (node instanceof Order order && RestrictionModifierRules.sortedBag(order)) {
			return potentialSeeks(order.getArg(), consumed);
		}
		if (node instanceof Slice slice && RestrictionModifierRules.noOpSlice(slice)) {
			return potentialSeeks(slice.getArg(), consumed);
		}
		if (node instanceof Group group && RestrictionModifierRules.wholeGroups(group)) {
			Set<String> names = new HashSet<>(potentialSeeks(group.getArg(), consumed));
			names.retainAll(group.getGroupBindingNames());
			return names;
		}
		if (node instanceof Join || node instanceof Union || node instanceof LeftJoin || node instanceof Difference) {
			BinaryTupleOperator binary = (BinaryTupleOperator) node;
			Set<String> names = new HashSet<>(potentialSeeks(binary.getLeftArg(), consumed));
			names.addAll(externalRightSeeks(binary, potentialSeeks(binary.getRightArg(), consumed)));
			names.retainAll(node.getBindingNames());
			return names;
		}
		return Set.of();
	}

	private static Set<String> externalRightSeeks(BinaryTupleOperator operator, Set<String> candidates) {
		Set<String> names = new HashSet<>(candidates);
		if (operator instanceof LeftJoin) {
			names.retainAll(operator.getLeftArg().getBindingNames());
		} else if (operator instanceof Difference) {
			names.retainAll(
					MinusQueryEvaluationStep.comparisonBindingNames(operator.getLeftArg(), operator.getRightArg()));
		}
		names.retainAll(operator.getBindingNames());
		return names;
	}

	private static Set<String> projectNames(Set<String> output, Function<String, String> sources, Set<String> child) {
		Set<String> names = new HashSet<>();
		for (String name : output) {
			String source = sources.apply(name);
			if (source != null && child.contains(source)) {
				names.add(name);
			}
		}
		return names;
	}

	public static int[] transfer(RestrictionLayout source, RestrictionLayout target, Function<String, String> map) {
		int[] transfer = new int[source.size()];
		for (int i = 0; i < transfer.length; i++) {
			String name = map.apply(source.name(i));
			transfer[i] = name == null ? -1 : target.slot(name);
		}
		return transfer;
	}

	private static List<List<Integer>> slotMaps(int[]... transfers) {
		return Arrays.stream(transfers).map(map -> Arrays.stream(map).boxed().toList()).toList();
	}

	private static Set<String> mappedSeeks(RestrictionLayout layout, PreparedRestrictionPlan child, int[] transfer) {
		Set<String> names = new HashSet<>();
		for (int slot = 0; slot < transfer.length; slot++) {
			if (transfer[slot] >= 0 && child.seekNames().contains(child.layout().name(transfer[slot]))) {
				names.add(layout.name(slot));
			}
		}
		return names;
	}

	public static CloseableIteration<BindingSet> residual(CloseableIteration<BindingSet> original,
			RestrictionFrame frame) {
		if (frame.isUnrestricted()) {
			return original;
		}
		return new ResidualIteration(original, frame);
	}

	private static final class ResidualIteration extends LookAheadIteration<BindingSet>
			implements IndexReportingIterator {
		private final CloseableIteration<BindingSet> original;
		private final RestrictionFrame frame;
		private final IndexReportingIterator reporter;

		private ResidualIteration(CloseableIteration<BindingSet> original, RestrictionFrame frame) {
			this.original = original;
			this.frame = frame;
			this.reporter = original instanceof IndexReportingIterator index ? index : null;
		}

		@Override
		protected BindingSet getNextElement() {
			while (!isCancellationRequested() && original.hasNext()) {
				if (isCancellationRequested()) {
					return null;
				}
				BindingSet row = original.next();
				if (frame.accepts(row)) {
					return row;
				}
			}
			return null;
		}

		@Override
		protected boolean forwardCancellation() {
			CooperativeCancellation.forward(original);
			return true;
		}

		@Override
		protected void handleClose() {
			original.close();
		}

		@Override
		public String getIndexName() {
			return reporter == null ? "" : reporter.getIndexName();
		}

		@Override
		public long getSourceRowsScannedActual() {
			return reporter == null ? -1 : reporter.getSourceRowsScannedActual();
		}

		@Override
		public long getSourceRowsMatchedActual() {
			return reporter == null ? -1 : reporter.getSourceRowsMatchedActual();
		}

		@Override
		public long getSourceRowsFilteredActual() {
			return reporter == null ? -1 : reporter.getSourceRowsFilteredActual();
		}
	}
